-- Check if scanpointcloud can be linked to sites through scans or other means
SELECT sp.cloudregistry, sp.arcref, s.zoneref 
FROM scanpointcloud sp JOIN scans s ON sp.arcref = s.arcref LIMIT 5;

-- Check scanspatial join through scans
SELECT ss.domainregistry, ss.arcref, s.zoneref 
FROM scanspatial ss JOIN scans s ON ss.arcref = s.arcref LIMIT 5;

-- Check features for SC1017
SELECT AVG(traitcount + articount) as avg_trait_arti
FROM scanfeatures WHERE zoneref = 'SC1017';
